import{_ as r,c as a,o as n,ag as i}from"./chunks/framework.CQuhCYrb.js";const f=JSON.parse('{"title":"Information for National Guard and Reserve Service Members","description":"","frontmatter":{"title":"Information for National Guard and Reserve Service Members"},"headers":[],"relativePath":"general/information-for-national-guard-and-reserve-service-members.md","filePath":"general/information-for-national-guard-and-reserve-service-members.md","lastUpdated":null}'),o={name:"general/information-for-national-guard-and-reserve-service-members.md"};function s(t,e,l,d,c,m){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="information-for-national-guard-and-reserve-service-members" tabindex="-1">Information for National Guard and Reserve Service Members <a class="header-anchor" href="#information-for-national-guard-and-reserve-service-members" aria-label="Permalink to &quot;Information for National Guard and Reserve Service Members&quot;">​</a></h1><h2 id="resources-and-information-for-national-guard-and-reserve-service-members" tabindex="-1">Resources and Information for National Guard and Reserve Service Members <a class="header-anchor" href="#resources-and-information-for-national-guard-and-reserve-service-members" aria-label="Permalink to &quot;Resources and Information for National Guard and Reserve Service Members&quot;">​</a></h2><p>This page provides valuable resources and information specifically for non-active military personnel in the National Guard and Reserves.</p><p><a href="https://www.reserve.uscg.mil/Resources/CG131/CG1311/Training/EBDL/" target="_blank" rel="noreferrer">Reserve Training and EBDL Resources</a></p><h3 id="money-and-pay" tabindex="-1">Money and Pay <a class="header-anchor" href="#money-and-pay" aria-label="Permalink to &quot;Money and Pay&quot;">​</a></h3><h3 id="electronic-based-distributed-learning-ebdl-for-pay" tabindex="-1">Electronic Based Distributed Learning (EBDL) for Pay <a class="header-anchor" href="#electronic-based-distributed-learning-ebdl-for-pay" aria-label="Permalink to &quot;Electronic Based Distributed Learning (EBDL) for Pay&quot;">​</a></h3><p>EBDL provides an opportunity for service members to be paid for up to 40 active-duty hours per year. This is beyond the typical Distance Learning Courses (DLC). Below are resources and approved course lists for EBDL:</p><ul><li><p><em>[EBDL Courses (PDF)]</em></p></li><li><p><a href="https://armyeitaas.sharepoint-mil.us/sites/USAR-USARC-G37/Documents%20LDD%20%20shared/Forms/AllItems.aspx?id=%2Fsites%2FUSAR%2DUSARC%2DG37%2FDocuments%20LDD%20%20shared%2FTAB%20A%20%2D%2020240208%20USAR%20EBDL%20List%2Epdf&amp;parent=%2Fsites%2FUSAR%2DUSARC%2DG37%2FDocuments%20LDD%20%20shared" target="_blank" rel="noreferrer">CAC-Only List</a></p></li></ul><h4 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to &quot;Additional Resources&quot;">​</a></h4><ul><li><p><a href="https://www.reserve.uscg.mil/Resources/Electronic-Based-Distributed-Learning-EBDL-/" target="_blank" rel="noreferrer">EBDL Guide (USCG)</a></p></li><li><p><a href="https://armyeitaas.sharepoint-mil.us/sites/USAR-USARC-G37/SitePages/Electronic-Based-Distributed-Learning.aspx" target="_blank" rel="noreferrer">Distance Learning (CAC)</a></p></li><li><p><a href="https://www.usar.army.mil/Portals/98/Documents/Publications/memos/USARC%20EBDL%20Policy%2001DEC22.pdf?ver=pGh_0OISL0qamXDwJTUvww%3d%3d" target="_blank" rel="noreferrer">2022 AFRC-OP (600-C) Memo (PDF)</a></p></li></ul>',10)])])}const p=r(o,[["render",s]]);export{f as __pageData,p as default};
